# Analyze the demonstrated canonical motif and possible dihedral variants
S={(0,2),(0,3),(1,0),(1,1),(2,2)}
def variants(shape):
    out=[]
    pts=list(shape)
    for k in range(4):
        for refl in [False, True]:
            trans=[]
            for r,c in pts:
                if refl: c=-c
                for _ in range(k): r,c=c,-r
                trans.append((r,c))
            mr=min(r for r,c in trans); mc=min(c for r,c in trans)
            v={(r-mr,c-mc) for r,c in trans}
            if v not in out: out.append(v)
    return out
