    template = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4}
    if not template:
        return out
    min_r = min(r for r, c in template)
    min_c = min(c for r, c in template)
    shape = {(r - min_r, c - min_c) for r, c in template}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    for color in range(2, 10):
        if color == 4:
            continue
        remaining = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color}
        while remaining:
            candidates = {}
            for r, c in remaining:
                for dr, dc in shape:
                    ar, ac = r - dr, c - dc
                    if ar < 0 or ac < 0 or ar + sh > h or ac + sw > w:
                        continue
                    cells = {(ar + sr, ac + sc) for sr, sc in shape}
                    covered = remaining & cells
                    if len(covered) >= 2:
                        candidates[(ar, ac)] = (covered, cells)
            if not candidates:
                break
            # Each copy is placed at the location supported by the largest set
            # of still-unassigned pixels; this also separates distant copies
            # of the same color.
            anchor = max(candidates, key=lambda a: (len(candidates[a][0]), -a[0], -a[1]))
            covered, cells = candidates[anchor]
            for r, c in cells:
                out[r][c] = color
            remaining -= covered
    return out
